INSERT INTO call_summaries (client_id, call_date, summary) VALUES ('C-01', '2026-09-29', 'Onboarding. Wants a drive-to place from northern NJ, ideally the Poconos. Prefers newer cabins with views. Has $300K set aside but said she could go a bit higher for the right house. Will use a co-host.');
INSERT INTO call_summaries (client_id, call_date, summary) VALUES ('C-01', '2026-10-15', 'Check-in. Liked the East Stroudsburg house but not the bigger renovation version of it. Wants to keep total cash under about $320K.');
INSERT INTO call_summaries (client_id, call_date, summary) VALUES ('C-02', '2026-08-14', 'Onboarding. High W-2 income; the priority is first-year depreciation. Open to any market. Fine managing a heavier renovation if the tax benefit is there.');
INSERT INTO call_summaries (client_id, call_date, summary) VALUES ('C-03', '2026-09-02', 'Onboarding. Couple said their range is $300K to $400K, but later mentioned they have $500K available from a home sale. Leaning beach. Not interested in mountain cabins.');
INSERT INTO call_summaries (client_id, call_date, summary) VALUES ('C-05', '2026-08-21', 'Onboarding. Wants the Smokies; family has vacationed in Gatlinburg for years. Budget around $275K, a little flexible.');
INSERT INTO call_summaries (client_id, call_date, summary) VALUES ('C-05', '2026-10-28', 'Check-in. Has been drawn to lake houses lately. Said ''the Smokies still feels like home'' but every Smokies cabin looks the same to her.');
INSERT INTO call_summaries (client_id, call_date, summary) VALUES ('C-06', '2026-07-30', 'Onboarding. Experienced investors. Want a large property they can transform and hold. Scottsdale is the top pick. Five bedrooms minimum.');
INSERT INTO call_summaries (client_id, call_date, summary) VALUES ('C-07', '2026-09-18', 'Onboarding. Wants a beach place to use a few weeks a year. Only needs it to break even. Does not want to manage renovations.');
INSERT INTO call_summaries (client_id, call_date, summary) VALUES ('C-08', '2026-09-10', 'Onboarding. Lives in Brooklyn, wants a ski house within three hours. Mentioned Hunter and Windham. Poconos is a backup.');
INSERT INTO call_summaries (client_id, call_date, summary) VALUES ('C-08', '2026-10-20', 'Check-in. Still wants skiing above all. Would consider the Poconos only if it''s near a mountain.');
INSERT INTO call_summaries (client_id, call_date, summary) VALUES ('C-09', '2026-10-08', 'Onboarding. Family-oriented couple. Strong concern about parties damaging the house. Want somewhere families visit. Any market otherwise.');
INSERT INTO call_summaries (client_id, call_date, summary) VALUES ('C-10', '2026-08-05', 'Onboarding. Based in Houston. Prefers San Antonio. Has a property manager friend who charges 12%.');
INSERT INTO call_summaries (client_id, call_date, summary) VALUES ('C-11', '2026-09-25', 'Onboarding. Wants Shenandoah or north Georgia, newer build, light work only. Budget $260K.');
INSERT INTO call_summaries (client_id, call_date, summary) VALUES ('C-12', '2026-11-10', 'Onboarding. First-time investor. Undecided on location. Said ''somewhere we''d actually want to vacation, maybe mountains or a lake.'' Budget about $350K.');
INSERT INTO call_summaries (client_id, call_date, summary) VALUES ('C-13', '2026-10-20', 'Onboarding. Selling a rental and doing a 1031 exchange. Must identify a property by December 20. Likes secluded cabins, Broken Bow or the Smokies.');
INSERT INTO call_summaries (client_id, call_date, summary) VALUES ('C-14', '2026-09-12', 'Onboarding. Tight budget, strict. Wants cash flow. Will use a co-host at 12% since he works long hours.');
INSERT INTO call_summaries (client_id, call_date, summary) VALUES ('C-15', '2026-08-28', 'Onboarding. Owns one STR in Bradenton. Wants a second on the water, Florida panhandle or Gulf coast. Comfortable with a big renovation.');
INSERT INTO call_summaries (client_id, call_date, summary) VALUES ('C-15', '2026-10-12', 'Check-in. Changed her mind on a Clearwater deal after a second look with her partner.');
INSERT INTO call_summaries (client_id, call_date, summary) VALUES ('C-02', '2026-10-14', 'Check-in. Passed on a Smokies deal only because of timing; still very interested in the area for next quarter.');
INSERT INTO call_summaries (client_id, call_date, summary) VALUES ('C-04', '2026-10-01', 'Onboarding. Small budget, wants turnkey and minimal amenities. Open to anywhere with steady demand.');
