-- Synthetic seed data for the STR Search take-home. Postgres 13+.
BEGIN;

CREATE TABLE markets (
  id TEXT PRIMARY KEY, name TEXT NOT NULL, state TEXT NOT NULL, towns JSONB NOT NULL,
  setting TEXT NOT NULL, typical_traveler TEXT, annual_appreciation NUMERIC, land_value_pct NUMERIC
);
CREATE TABLE deals (
  id TEXT PRIMARY KEY, address TEXT, city TEXT, state TEXT, purchase_price NUMERIC NOT NULL,
  bedrooms INT, baths NUMERIC, lot_acres NUMERIC, turnkey BOOLEAN, interest_rate NUMERIC, closing_cost_pct NUMERIC,
  setup_items JSONB, annual_opex NUMERIC, revenue JSONB, est_year1_tax_savings NUMERIC, comps JSONB,
  highlights JSONB, analyst_notes TEXT, approved_at DATE
);
CREATE TABLE clients (
  id TEXT PRIMARY KEY, name TEXT, budget_range TEXT, budget NUMERIC, budget_flexibility TEXT,
  down_payment_pct NUMERIC, cohost_fee_pct NUMERIC, main_focus TEXT, market_preferences JSONB, avoid_markets JSONB,
  setting_rank JSONB, renovation_appetite TEXT, wow_factors JSONB, wants_turnkey BOOLEAN, min_bedrooms INT,
  notes TEXT, onboarded_at DATE
);
CREATE TABLE feedback (
  id SERIAL PRIMARY KEY, client_id TEXT REFERENCES clients(id), deal_id TEXT REFERENCES deals(id),
  reaction TEXT CHECK (reaction IN ('up','down')), comment TEXT, created_at DATE
);
CREATE TABLE call_summaries (
  id SERIAL PRIMARY KEY, client_id TEXT REFERENCES clients(id), call_date DATE, summary TEXT
);
COMMIT;
